import java.util.ArrayList;
import java.util.List;

public class Tasks {
    public static void main(String[] args) {
        List<String> tasks = new ArrayList<>();
        tasks.add("write code");
        tasks.add("test code");
        tasks.add("ship");
        tasks.add(1, "review");           // insert at index 1
        System.out.println(tasks);
        System.out.println(tasks.size() + " tasks, first: " + tasks.getFirst());
        tasks.set(0, "write tests");       // replace the element at index 0
        tasks.remove("ship");              // remove by value
        System.out.println(tasks.contains("ship") + " " + tasks.indexOf("review"));
        for (String task : tasks) {
            System.out.println("- " + task);
        }
    }
}

List<Integer> fixed = List.of(3, 1, 2);
List<Integer> numbers = new ArrayList<>(fixed);
numbers.add(0);
Collections.sort(numbers);
System.out.println(numbers);
System.out.println(numbers.reversed());
try {
    fixed.add(4);
} catch (UnsupportedOperationException e) {
    System.out.println("List.of() lists cannot change");
}

Set<String> seen = new HashSet<>();
String[] visits = {"ada", "bob", "ada", "cy", "bob"};
for (String visit : visits) {
    boolean added = seen.add(visit);
    System.out.println(visit + " new? " + added);
}
System.out.println(seen.size() + " unique visitors");
Set<String> sorted = new TreeSet<>(seen);
System.out.println(sorted);

Map<String, Integer> stock = new LinkedHashMap<>();
stock.put("apple", 5);
stock.put("pear", 2);
stock.put("apple", 7);                 // replaces the value for apple
System.out.println(stock);
System.out.println(stock.get("pear"));
System.out.println(stock.get("kiwi"));
System.out.println(stock.getOrDefault("kiwi", 0));
stock.merge("pear", 3, Integer::sum);   // 2 + 3
stock.merge("kiwi", 1, Integer::sum);   // absent, so stored as 1
for (Map.Entry<String, Integer> entry : stock.entrySet()) {
    System.out.println(entry.getKey() + " -> " + entry.getValue());
}

List<Integer> numbers = new ArrayList<>(List.of(5, 1, 8, 1, 3));
numbers.remove(1);                   // index 1: removes the first 1
numbers.remove(Integer.valueOf(1));  // value 1: removes the other 1
System.out.println(numbers);
numbers.removeIf(n -> n > 4);        // safe removal by condition
System.out.println(numbers);
